// Custom Worker entry: wraps the OpenNext-generated worker to add a cron
// (scheduled) handler and an edge snapshot layer. `.open-next/worker.js` is
// generated by `npm run build`.
import handler from "./.open-next/worker.js";

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

// ---------------------------------------------------------------------------
// Edge snapshot layer — "build once, serve to everyone".
//
// These public endpoints return the same answer for every visitor (match
// lists, flags, scores, settings). Instead of letting every visitor's request
// run the app and query the database, the answer is built once and the copy
// is handed to everyone:
//
//   1. this Worker instance's memory            (free, instant)
//   2. Cloudflare's edge cache in the visitor's city  (shared by all instances)
//   3. KV, written by the every-minute cron     (global last-good copy)
//   4. the app itself — at most about once per `fresh` seconds per city,
//      with one refresher at a time; everyone else gets the copy meanwhile.
//
// So database load no longer grows with the crowd. If the app or database
// is slow or failing, visitors keep getting the last good copy instead of an
// empty page. A response is only stored when it is a clean 200 JSON answer
// with no cookies and no "degraded" marker, so a bad moment is never frozen
// into the copy.
// ---------------------------------------------------------------------------

// path -> { fresh: seconds a copy counts as current, params: query params
// that change the answer (everything else, e.g. cache-busting ?t=, is
// ignored), snapshot: also kept in KV by the cron }
const RULES = {
  "/api/match-flags": { fresh: 10, params: [], snapshot: true },
  "/api/live-matches": { fresh: 10, params: [], snapshot: true },
  "/api/pro-matches": { fresh: 15, params: ["page"], snapshot: true },
  "/api/alt-scores": { fresh: 20, params: [], snapshot: true },
  "/api/maintenance-status": { fresh: 15, params: [], snapshot: true },
  "/api/leagues": { fresh: 120, params: [], snapshot: true },
  "/api/matches": { fresh: 30, params: ["sport"], snapshot: false },
  "/api/live-score": { fresh: 20, params: ["home", "away"], snapshot: false },
  "/api/final-score": { fresh: 30, params: ["home", "away"], snapshot: false },
  "/api/announcement": { fresh: 60, params: [], snapshot: true },
  "/api/social-links": { fresh: 300, params: [], snapshot: true },
  "/api/vpn-config": { fresh: 300, params: [], snapshot: true },
  "/api/help-content": { fresh: 300, params: [], snapshot: true },
};

// Per-match endpoints: one copy per match (the path carries the match id),
// shared by everyone watching that match.
const PREFIX_RULES = [
  { prefix: "/api/match-streams/", rule: { fresh: 20, params: ["title", "sport", "kickoff"], snapshot: false } },
  { prefix: "/api/match-meta/", rule: { fresh: 30, params: [], snapshot: false } },
  { prefix: "/api/stream-override/", rule: { fresh: 20, params: [], snapshot: false } },
];
// The watch page reads the public ad settings from here too (GET only;
// saving still goes straight to the app).
RULES["/api/admin/ads-config"] = { fresh: 30, params: [], snapshot: false };
RULES["/api/tv-channels"] = { fresh: 60, params: [], snapshot: false };

function ruleFor(pathname) {
  if (RULES[pathname]) return RULES[pathname];
  for (const r of PREFIX_RULES) if (pathname.startsWith(r.prefix) && pathname.length > r.prefix.length) return r.rule;
  return null;
}

const MAX_STALE_SEC = 6 * 3600; // a copy this old is still better than nothing
const ORIGIN_TIMEOUT_MS = 10_000;
const LOCK_SEC = 15; // one refresher per city at a time
const CACHE_HOST = "https://edge-snapshot.primepitch.internal";

const mem = new Map(); // key -> snap { at, ct, body }
const inflight = new Map(); // key -> Promise<{ snap, res }>

function snapKey(path, rule, url) {
  if (!rule.params.length) return path;
  const qs = rule.params
    .map((p) => `${p}=${encodeURIComponent(url.searchParams.get(p) || "")}`)
    .join("&");
  return `${path}?${qs}`;
}

function respond(snap, how) {
  return new Response(snap.body, {
    status: 200,
    headers: {
      "content-type": snap.ct || "application/json",
      "cache-control": "no-store",
      "x-edge": how,
      "x-edge-age": String(Math.max(0, Math.round((Date.now() - snap.at) / 1000))),
    },
  });
}

async function cacheGet(key) {
  try {
    const r = await caches.default.match(new Request(CACHE_HOST + key));
    if (!r) return null;
    const at = Number(r.headers.get("x-snap-at") || 0);
    const fresh = Number(r.headers.get("x-snap-fresh") || 0);
    return { at, ct: r.headers.get("content-type"), body: await r.text(), ...(fresh > 0 ? { fresh } : {}) };
  } catch {
    return null;
  }
}

async function cachePut(key, snap) {
  try {
    await caches.default.put(
      new Request(CACHE_HOST + key),
      new Response(snap.body, {
        headers: {
          "content-type": snap.ct || "application/json",
          "x-snap-at": String(snap.at),
          ...(snap.fresh ? { "x-snap-fresh": String(snap.fresh) } : {}),
          "cache-control": `public, max-age=${MAX_STALE_SEC}`,
        },
      })
    );
  } catch {
    /* edge cache is best effort */
  }
}

async function kvGet(env, key) {
  if (!env.SNAP) return null;
  try {
    const v = await env.SNAP.get("snap:" + key, { type: "json", cacheTtl: 30 });
    return v && v.body != null ? v : null;
  } catch {
    return null;
  }
}

async function kvPut(env, key, snap) {
  if (!env.SNAP) return;
  try {
    await env.SNAP.put("snap:" + key, JSON.stringify(snap), { expirationTtl: 2 * 86400 });
  } catch {
    /* KV is best effort */
  }
}

// Lock so that, per city, only one instance refreshes a given copy at a time.
async function takeLock(key) {
  try {
    const lockReq = new Request(CACHE_HOST + "/__lock" + key);
    if (await caches.default.match(lockReq)) return false;
    await caches.default.put(
      lockReq,
      new Response("1", { headers: { "cache-control": `public, max-age=${LOCK_SEC}` } })
    );
    return true;
  } catch {
    return true;
  }
}

function isCleanJson(res) {
  if (res.status !== 200) return false;
  if (res.headers.get("set-cookie")) return false;
  if (res.headers.get("x-pp-degraded")) return false;
  return (res.headers.get("content-type") || "").includes("json");
}

// Ask the app for a fresh copy (once per instance at a time). Returns the
// snapshot when the answer is clean, plus the raw response for pass-through.
function refresh(key, env, ctx, { useCache }) {
  if (inflight.has(key)) return inflight.get(key);
  const p = (async () => {
    const origin = env.NEXT_PUBLIC_SITE_URL || "https://primepitch.daxonicstudios.workers.dev";
    const req = new Request(origin + key, { headers: { accept: "application/json" } });
    let res;
    try {
      res = await Promise.race([
        handler.fetch(req, env, ctx),
        new Promise((_, rej) => setTimeout(() => rej(new Error("origin timeout")), ORIGIN_TIMEOUT_MS)),
      ]);
    } catch {
      return { snap: null, res: null };
    }
    if (!isCleanJson(res)) return { snap: null, res };
    // A route can ask for a shorter life for this answer (e.g. "no streams
    // yet" right before kickoff) with x-edge-fresh: <seconds>.
    const f = Number(res.headers.get("x-edge-fresh") || 0);
    const snap = { at: Date.now(), ct: res.headers.get("content-type"), body: await res.text(), ...(f > 0 ? { fresh: f } : {}) };
    mem.set(key, snap);
    if (useCache) await cachePut(key, snap);
    return { snap, res: null };
  })().finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}

async function edgeServe(request, env, ctx, path, rule) {
  const url = new URL(request.url);
  const key = snapKey(path, rule, url);
  const now = Date.now();
  const freshOf = (snap) => (snap.fresh || rule.fresh) * 1000;
  // The Cache API does nothing on *.workers.dev; there KV is the shared layer.
  const useCache = !url.hostname.endsWith(".workers.dev");

  const m = mem.get(key);
  if (m && now - m.at < freshOf(m)) return respond(m, "mem");

  let shared = useCache ? await cacheGet(key) : null;
  if (shared && now - shared.at < freshOf(shared)) {
    mem.set(key, shared);
    return respond(shared, "hit");
  }
  if (!shared && !m && rule.snapshot) shared = await kvGet(env, key);

  const stale = [m, shared].filter(Boolean).sort((a, b) => b.at - a.at)[0];
  if (stale && now - stale.at < MAX_STALE_SEC * 1000) {
    // Serve the copy now; refresh it in the background (one refresher per city).
    ctx.waitUntil(
      (async () => {
        if (!useCache || (await takeLock(key))) await refresh(key, env, ctx, { useCache });
      })()
    );
    return respond(stale, "stale");
  }

  // Nothing usable yet: wait for the app this once.
  const { snap, res } = await refresh(key, env, ctx, { useCache });
  if (snap) return respond(snap, "miss");
  if (res) return res;
  return new Response(JSON.stringify({ error: "temporarily unavailable" }), {
    status: 503,
    headers: { "content-type": "application/json", "cache-control": "no-store", "retry-after": "5" },
  });
}

// Every minute: refresh the KV copy of each parameter-free snapshot, so every
// city has a recent last-good copy even before its own edge cache fills.
async function snapshotAll(env, ctx) {
  if (!env.SNAP) return;
  for (const [path, rule] of Object.entries(RULES)) {
    if (!rule.snapshot || rule.params.length) continue;
    const { snap } = await refresh(path, env, ctx, { useCache: false });
    if (snap) await kvPut(env, path, snap);
  }
  // pro-matches as the Big Matches page asks for it (no page param).
  const pro = snapKey("/api/pro-matches", RULES["/api/pro-matches"], new URL(CACHE_HOST + "/"));
  const { snap } = await refresh(pro, env, ctx, { useCache: false });
  if (snap) await kvPut(env, pro, snap);
}

export default {
  async fetch(request, env, ctx) {
    if (request.method === "GET") {
      const url = new URL(request.url);
      const rule = ruleFor(url.pathname);
      // Admins (signed-in cookie) always see the live answer, so a change they
      // just made shows at once. (The layer's own refreshes call the app
      // directly, never through here.)
      const isAdmin = /(?:^|;\s*)pp_admin=/.test(request.headers.get("cookie") || "");
      if (rule && !isAdmin && url.searchParams.get("admin") !== "true") {
        return edgeServe(request, env, ctx, url.pathname, rule);
      }
    }
    return handler.fetch(request, env, ctx);
  },

  // See [triggers] in wrangler.toml. Every-minute tick runs the auto-live
  // kickoff check and refreshes the KV snapshots; the daily tick runs the
  // big-game picker. Dispatches into the app without leaving the worker.
  async scheduled(event, env, ctx) {
    const origin = env.NEXT_PUBLIC_SITE_URL || "https://primepitch.daxonicstudios.workers.dev";
    const path =
      event.cron === "0 0 * * *"
        ? "/api/cron/auto-pick"
        : event.cron === "5 * * * *"
          ? "/api/cron/sync-ga4"
          : event.cron === "0 5 * * *"
            ? "/api/cron/alt-refresh"
            : "/api/cron/auto-live";
    const request = new Request(`${origin}${path}`, {
      headers: { authorization: `Bearer ${env.CRON_SECRET || "secret"}` },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
    if (event.cron === "* * * * *") ctx.waitUntil(snapshotAll(env, ctx));
  },
};
